package com.bank.rightview;

import java.util.*;

public class RightViewService {

    public List<Integer> rightView(ViewNode root) {
        List<Integer> view = new ArrayList<>();
        if (root == null) return view;

        Queue<ViewNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                ViewNode node = queue.poll();
                if (i == levelSize - 1) view.add(node.id);   // last node of this level
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
        }
        return view;
    }
}
