package com.bank.rightview;

import java.util.logging.Logger;

public class RightViewDemo {
    private static final Logger log = Logger.getLogger(RightViewDemo.class.getName());

    public static void main(String[] args) {
        // Tree:        1
        //            /   \
        //           2     3
        //          /
        //         4            right view = [1, 3, 4]
        ViewNode root = new ViewNode(1);
        root.left = new ViewNode(2);
        root.right = new ViewNode(3);
        root.left.left = new ViewNode(4);

        log.info("Right view: " + new RightViewService().rightView(root));
    }
}
